  VALUES 
    (521::BIGINT, 'Expica muy bien resolviendo ejemplos en su tablet y pasa los apuntes a sus estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '0c417336ed3b49ced28697dc4c1aabc314db06c7f90297d1c3af4dcfffb8e8db'::TEXT, ARRAY[605]::BIGINT[]),
    (521::BIGINT, 'Un tanto aburrido pero estoy seguro que no es completamente culpa del profe, simplemente Estadística es así jaja. Si no hay otro profe como "wow", es una buena opción. Hace quices cada cierto tiempo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, '3f1b87e169985c58035f5f7e88ece1e87c6b88c649524462ff51f9b77454ffc1'::TEXT, ARRAY[1057]::BIGINT[]),
    (521::BIGINT, 'Top profesores del tec en cuanto a la escuela de mate, explica demasiado bien, sus presentaciones acerca de la materia son increibles y super bien estructuradas, si pueden matricular con el, haganlo!!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases largas']::TEXT[], '2026-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c279309311d9c9c489469fd38c85c8f04683fe7935a1fb2c9eac65b5a8275bc0'::TEXT, ARRAY[1018]::BIGINT[]),
    (521::BIGINT, 'Es un excelente profe, yo llevé Mate General y CDI con él. Prepara las clases en presentaciones y los comparte para nuestra facilidad, hace bastante práctica y explica muy bien. Es muy amable.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-04-24T00:00:00+00:00'::TIMESTAMPTZ, '16704180f7cc145ec60490e070ab432ea58ed7a2d80ccdcb452031549ddac856'::TEXT, ARRAY[605]::BIGINT[]),
    (521::BIGINT, 'Leonel es un profe excelente para estadística, siempre la materia se entendía a la perfección y el es muy amable con los estudiantes. No importa cuántas veces tenga que explicar algo de nuevo lo hace hasta que uno entienda, le encanta ayudar y se pone a disposición siempre.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, '72e0d2fb9b8e4469257822147d95642c9745e353af2c50343fa14f6d55a15913'::TEXT, ARRAY[1057]::BIGINT[]),
    (521::BIGINT, 'El profesor explica muy bien y califica suave, el curso en sí es duro pero con él se aprende bien.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2026-02-18T00:00:00+00:00'::TIMESTAMPTZ, '52e0eaa8681d2e1adeef8a0661bbd9fe8ec564b700dc2f81c7080d6aca3fc5d2'::TEXT, ARRAY[605]::BIGINT[]),
    (521::BIGINT, 'Explica muy bien y califica bastante suave, las tareas que deja sirven de apoyo para los exámenes. Lo recomiendo bastante (principalmente a quienes repiten CAL)'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-02-05T00:00:00+00:00'::TIMESTAMPTZ, 'a0dfd1d95a43783e21cec3086ff8bf5a47194ad0aaaea789ce547635628d4319'::TEXT, ARRAY[634]::BIGINT[]),
    (521::BIGINT, 'Por la naturaleza del curso, estadistica es facil, sin embargo, leo lo hace muy llevadero, sin que este muy pesado, mas sabiendo que los cursos que se lleven junto a este son pesados. Tarda en enviar notas pero califica justo y ayudando al estudiante'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, '04480bd6d807b5bdbe51445a896cf81be949f6b63e6fbf9c40af08ae4e6021e4'::TEXT, ARRAY[1057]::BIGINT[]),
    (521::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '5fa08ab63d805b47b3de6c47c903b8a48b52df39e1b3f2bf71353b106225ca9f'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Es muy buen profe, se nota que le gusta lo que hace. Hace pocas evaluaciones, pero bastante fáciles, si es la primera vez llevando el curso lo recomiendo. Llevaría con él otra vez sin duda.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '4ee87d6eac35a5cbc2e9fe78ab5e4dcb3ff3f25b4919a725b2aa376e87d733bf'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Es un crack, explica demasiado bien, buena gente, tiene muy bien estructurado las tareas, quices. Me quedé pero fue por mi culpa el profe lo hace muy bien'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'a8b503577127c071253469257b01ee03d3f85dea2d854e90c8701b4da66b0cb3'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Explica muy bien, deja una tarea y un quiz por parcial y valen como 2% cada uno, sube TODOS los apuntes de la clase entonces puede ir y solo poner atención pasa mucha practica antes del examen, es muy buena gente y no califica tan duro muy recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-19T00:00:00+00:00'::TIMESTAMPTZ, '08f40878559383651a06838305692ed74687df7657958a9414cbd1f9b7f49b74'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Es muy buen profesor, si uno no entiende explica sin ningun problema de nuevo. Los ejercicios y explicaciones los hace mediante diapositivas y luego de la clase los sube al tec digital. Muy amable y es bueno calificando.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-06-16T00:00:00+00:00'::TIMESTAMPTZ, '509979aa6c1602769badff3f42979ad3d7be96bbe307d372bcc4490a06e8c9f2'::TEXT, ARRAY[1018, 563]::BIGINT[]),
    (521::BIGINT, 'Excelente profesor ,realmente me ayudo mucho en mate . Volvería a llevar un curso con el .'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2025-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'e4689872f2a927b016097ac2d7ee5e6b06e7faefde62e184982b5e110dbb3591'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Muy buen profe, explica todo super bien, si tiene que repetir lo repite y de buena manera. Carismático y buena gente. Hace muchos ejemplos en clase, los apuntes son buenisimos sirven para estudiar y las prácticas super buenas. Si se presta atención se pasa 100%'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2025-05-20T00:00:00+00:00'::TIMESTAMPTZ, '4b9bef7e8556a815f0722d085d07aa29fb48f46a5e982d90b224503df72c71e0'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Es simplemente el mejor profesor de matemáticas del TEC, recomiendo matricular con el 100%, me cambio la vida y ahora me gusta la matemática. Gracias profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-05-09T00:00:00+00:00'::TIMESTAMPTZ, '8220d96e9e675ab9b27c4ad363abccb534e00ef2d28679897a6506c77610a6d0'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Muy buen profesor, realmente ayuda mucho y siempre tiene una actitud positiva a la hora de enseñar. Da demasiado apoyo para poder estudiar si uno no entendió una clase o se perdió de algo, subiendo las presentaciones al tec digital. Excelente profesor, definitivamente llevaría otra clase con él. ????'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-01-24T00:00:00+00:00'::TIMESTAMPTZ, '9ecf3962970090c64feb6c74e05943b83dceb242b982b8a108f2b27994a0f5b2'::TEXT, ARRAY[605]::BIGINT[]),
    (521::BIGINT, 'Pone una tarea y un quiz por cada parcial, y siempre hace un repaso la clase antes del examen, da buena retroalimentación y explica bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2025-01-21T00:00:00+00:00'::TIMESTAMPTZ, 'cb2e7d8dc0c3486ad5bdcc93b96fd118f4b8e89e5f505116688b72489d0d2715'::TEXT, ARRAY[605]::BIGINT[]),
    (521::BIGINT, 'Es un excelente profesor tanto si está repitiendo la materia o si le está llevando por primera vez, explica muy bien, no evalúa tan duro y en consulta ayuda demasiado, extremadamente recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, '9b48d73b3c015bfe255ceaff8902e720d4e50a40eb91c234dcbb7adadfc03647'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Buen profesor, califica algo duro y brinda ayuda en consulta'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'feff1c56a429dd7778217d97fc7e61fc596018af5aa378ecd9379b2bcc9ae4e4'::TEXT, ARRAY[634]::BIGINT[]),
    (521::BIGINT, 'Es buena opción si está repitiendo el curso, el solo se sienta a resolver ejercicios en lugar de explicar los conceptos de cero. Hace muy pocas evaluaciones entonces queda muy tallado. Explica las veces necesarias pero no se relaciona mucho con el estudiante, resuelve ejercicios, deja quices y listo'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '66286fc094c68bb12b1d6549f0db67af4b8fe93dcd9c3a546c00fc13aa347690'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Excelente profesor para llevar CAL. Explica todo demasiado claro, da varios ejemplos e incluso saca tiempo para una clase de repaso aunque no esté en el cronograma del curso. Definitivamente volvería a llevar cualquier curso de mate con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '2d695dc4768022ba1e6b6dc8ef5f6291a2a3bfb5b07c0fdfc4ee29e7f2ea08d5'::TEXT, ARRAY[634]::BIGINT[]),
    (521::BIGINT, 'Es verdad que el profe explica algo rápido, pero la verdad es muy buena gente y si usted no entiende él le explica las veces que sean necesarias. Si no le cuesta la mate y entiende rápido los temas, no va a tener problemas.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '85be7fc0fa40834926c7c895ac2a2cb48893e613a4950f71dcb8b382c64bf9cf'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'El profe básicamente solo se sienta a resolver ejercicios, espera que uno ya entienda conceptos y no explica bien La clase es muy poco dinámica, entonces es muy aburrida'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2024-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'b5e7ff14af9a923409d747350f48084885903296df219cf8c154ceaabbeb5db9'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Si usted quiere pasar matemáticas general no matricule con Leonel y olvídese el 25% que son de quiz ya lo perdió lo único bueno es que envía las diapositivas que explica'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2024-05-24T00:00:00+00:00'::TIMESTAMPTZ, 'ab7f4a0bf681e0be508bcefe16f8e48a3563c46246c17957d5800f7db3d48ffc'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Explica demasiado rápido entonces es difícil seguirle el ritmo en clase, asume que ya uno llega sabiendo los conceptos matemáticos de los que habla. Eso si, siempre manda las presentaciones que usa al grupo, pero debería explicar con más paciencia y no llevar la materia tan a la carrera.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2024-05-23T00:00:00+00:00'::TIMESTAMPTZ, 'f6ac07b9e3b13e764b3657ca64c8d8fe775beedb652a5769a7b73bf192608bb1'::TEXT, ARRAY[563]::BIGINT[]),
    (521::BIGINT, 'Solo califica exámenes cortos además de los parciales. En sus clases no explica con claridad'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-05-14T00:00:00+00:00'::TIMESTAMPTZ, 'ec7e79dcd794215b2fdaae82557e478212ab6b2833282111548348a9d76c99ed'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
